class Solution {
    public int carFleet(int target, int[] position, int[] speed) {
        int n = position.length;
        int[][] cars = new int[n][2];

        for (int i = 0; i < n; i++) {
            cars[i][0] = position[i];
            cars[i][1] = speed[i];
        }

        // 按位置从大到小排序（离终点最近的在前）
        Arrays.sort(cars, (a, b) -> b[0] - a[0]);

        int fleets = 0;
        double lastTime = 0;

        for (int[] car : cars) {
            double time = (double) (target - car[0]) / car[1];

            // 如果当前车到达时间 > 前一辆车，说明无法追上，形成新车队
            if (time > lastTime) {
                fleets++;
                lastTime = time;
            }
            // 否则会追上前车，合并到前面的车队
        }

        return fleets;
    }
}

class Solution {
    public int carFleet(int target, int[] position, int[] speed) {
        int n = position.length;
        double[][] cars = new double[n][2];

        for (int i = 0; i < n; i++) {
            cars[i][0] = position[i];
            cars[i][1] = (double) (target - position[i]) / speed[i];
        }

        // 按位置从大到小排序
        Arrays.sort(cars, (a, b) -> Double.compare(b[0], a[0]));

        Deque<Double> stack = new ArrayDeque<>();

        for (double[] car : cars) {
            double time = car[1];

            // 如果栈为空或当前车到达时间更长，压入栈
            if (stack.isEmpty() || time > stack.peek()) {
                stack.push(time);
            }
            // 否则当前车追上栈顶车队，不压入
        }

        return stack.size();
    }
}
